public class RegexTest {
    private static final Pattern TITLE_PATTERN = Pattern.compile(
            "<title[^>]*>(.*?)</title>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
    private static final Pattern META_DESCRIPTION_NAME_FIRST = Pattern.compile(
            "<meta[^>]+name\\s*=\\s*[\"']description[\"'][^>]+content\\s*=\\s*[\"']([^\"']*)[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern META_DESCRIPTION_CONTENT_FIRST = Pattern.compile(
            "<meta[^>]+content\\s*=\\s*[\"']([^\"']*)[\"'][^>]+name\\s*=\\s*[\"']description[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern FAVICON_REL_FIRST = Pattern.compile(
            "<link[^>]+rel\\s*=\\s*[\"'](?:shortcut\\s+)?icon[\"'][^>]+href\\s*=\\s*[\"']([^\"']*)[\"']",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern FAVICON_HREF_FIRST = Pattern.compile(
            "<link[^>]+href\\s*=\\s*[\"']([^\"']*)[\"'][^>]+rel\\s*=\\s*[\"'](?:shortcut\\s+)?icon[\"']",
            Pattern.CASE_INSENSITIVE);

    static String title(String html) {
        Matcher m = TITLE_PATTERN.matcher(html);
        return m.find() ? m.group(1).trim() : null;
    }
    static String desc(String html) {
        Matcher m = META_DESCRIPTION_NAME_FIRST.matcher(html);
        if (m.find()) return m.group(1).trim();
        m = META_DESCRIPTION_CONTENT_FIRST.matcher(html);
        return m.find() ? m.group(1).trim() : null;
    }
    static String fav(String html) {
        Matcher m = FAVICON_REL_FIRST.matcher(html);
        if (m.find()) return m.group(1).trim();
        m = FAVICON_HREF_FIRST.matcher(html);
        return m.find() ? m.group(1).trim() : null;
    }

    static void check(String label, Object actual, Object expected) {
        boolean ok = expected == null ? actual == null : expected.equals(actual);
        System.out.println((ok ? "PASS" : "FAIL") + " " + label + " => " + actual + (ok ? "" : " (expected " + expected + ")"));
        if (!ok) System.exit(1);
    }

    public static void main(String[] args) {
        String html1 = "<!DOCTYPE html><html><head>\n" +
                "<title>  Example Page  </title>\n" +
                "<meta name=\"description\" content=\"An example description\">\n" +
                "<link rel=\"icon\" href=\"/favicon.ico\">\n" +
                "</head><body>Hello</body></html>";
        check("title basic", title(html1), "Example Page");
        check("desc basic", desc(html1), "An example description");
        check("fav basic", fav(html1), "/favicon.ico");

        String html2 = "<HTML><HEAD><TITLE>Upper</TITLE>" +
                "<META NAME=\"DESCRIPTION\" CONTENT=\"Upper Desc\">" +
                "<LINK REL=\"SHORTCUT ICON\" HREF=\"/f.ico\"></HEAD></HTML>";
        check("title upper", title(html2), "Upper");
        check("desc upper", desc(html2), "Upper Desc");
        check("fav shortcut", fav(html2), "/f.ico");

        // content-before-name attribute order
        String html3 = "<html><head><meta content=\"Reversed\" name=\"description\">" +
                "<link href=\"/rev.ico\" rel=\"icon\"><title>T3</title></head></html>";
        check("desc reversed", desc(html3), "Reversed");
        check("fav reversed", fav(html3), "/rev.ico");

        // absent elements
        String html4 = "<html><head></head><body>nothing</body></html>";
        check("title absent", title(html4), null);
        check("desc absent", desc(html4), null);
        check("fav absent", fav(html4), null);

        // single quotes
        String html5 = "<title>T5</title><meta name='description' content='Single'><link rel='icon' href='/s.ico'>";
        check("desc single-quote", desc(html5), "Single");
        check("fav single-quote", fav(html5), "/s.ico");

        // og:description must NOT match name=description
        String html6 = "<html><head><meta property=\"og:description\" content=\"OG\"></head></html>";
        check("og not matched", desc(html6), null);

        // multiline title
        String html7 = "<title>\n  Multi\n  Line\n</title>";
        check("title multiline", title(html7), "Multi\n  Line");

        // keywords meta before description meta
        String html8 = "<meta name=\"keywords\" content=\"k\"><meta name=\"description\" content=\"D8\">";
        check("desc after keywords", desc(html8), "D8");

        System.out.println("ALL PASS");
    }
}
